changeSet.sql:
UPDATE configuration_properties AS stale SET property_key = 'xroad.proxy-ui-api.acme-certificate-wait-attempts' WHERE stale.property_key = 'xroad.proxy-ui-api.acme-certification-wait-attempts' AND NOT EXISTS (SELECT 1 FROM configuration_properties existing WHERE existing.property_key = 'xroad.proxy-ui-api.acme-certificate-wait-attempts' AND (existing.scope = stale.scope OR (existing.scope IS NULL AND stale.scope IS NULL)));
UPDATE configuration_properties AS stale SET property_key = 'xroad.proxy-ui-api.acme-certificate-wait-interval' WHERE stale.property_key = 'xroad.proxy-ui-api.acme-certification-wait-interval' AND NOT EXISTS (SELECT 1 FROM configuration_properties existing WHERE existing.property_key = 'xroad.proxy-ui-api.acme-certificate-wait-interval' AND (existing.scope = stale.scope OR (existing.scope IS NULL AND stale.scope IS NULL)));
DELETE FROM configuration_properties WHERE property_key IN ('xroad.proxy-ui-api.acme-certification-wait-attempts', 'xroad.proxy-ui-api.acme-certification-wait-interval');
